<template><div><h2 id="quick-start" tabindex="-1"><a class="header-anchor" href="#quick-start"><span><strong>Quick Start</strong></span></a></h2>
<h3 id="install-bash" tabindex="-1"><a class="header-anchor" href="#install-bash"><span>Install（bash）</span></a></h3>
<div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre v-pre><code><span class="line">pip <span class="token function">install</span> gma</span>
<span class="line"></span></code></pre>
<div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0"><div class="line-number"></div></div></div><h3 id="import-ide" tabindex="-1"><a class="header-anchor" href="#import-ide"><span>Import（IDE）</span></a></h3>
<div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py" data-title="py"><pre v-pre><code><span class="line"><span class="token comment">## Import selected modules</span></span>
<span class="line"><span class="token keyword">from</span> gma <span class="token keyword">import</span> climet<span class="token punctuation">,</span> crs<span class="token punctuation">,</span> driver<span class="token punctuation">,</span> gio<span class="token punctuation">,</span> math<span class="token punctuation">,</span> rsvi<span class="token punctuation">,</span> smc<span class="token punctuation">,</span> etools<span class="token punctuation">,</span> env<span class="token punctuation">,</span> const</span>
<span class="line"></span>
<span class="line"><span class="token comment">## Spatial plotting and built-in data</span></span>
<span class="line"><span class="token keyword">from</span> gma<span class="token punctuation">.</span>carto <span class="token keyword">import</span> plot<span class="token punctuation">,</span> inres </span>
<span class="line"></span></code></pre>
<div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="plotting-example" tabindex="-1"><a class="header-anchor" href="#plotting-example"><span>Plotting (Example)</span></a></h3>
<div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py" data-title="py"><pre v-pre><code><span class="line"><span class="token keyword">from</span> gma<span class="token punctuation">.</span>carto <span class="token keyword">import</span> plot<span class="token punctuation">,</span> inres</span>
<span class="line"><span class="token keyword">from</span> gma <span class="token keyword">import</span> crs</span>
<span class="line"><span class="token keyword">import</span> matplotlib<span class="token punctuation">.</span>pyplot <span class="token keyword">as</span> plt</span>
<span class="line"><span class="token keyword">import</span> numpy <span class="token keyword">as</span> np</span>
<span class="line"></span>
<span class="line">fig <span class="token operator">=</span> plt<span class="token punctuation">.</span>figure<span class="token punctuation">(</span>dpi <span class="token operator">=</span> <span class="token number">300</span><span class="token punctuation">)</span></span>
<span class="line">ax <span class="token operator">=</span> fig<span class="token punctuation">.</span>add_subplot<span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># Create a Bonne projection coordinate system with a central meridian of 112°E</span></span>
<span class="line">proj <span class="token operator">=</span> crs<span class="token punctuation">.</span>ProjectedCoordinateSystem<span class="token punctuation">(</span>proj_method <span class="token operator">=</span> crs<span class="token punctuation">.</span>ProjMethods<span class="token punctuation">.</span>Bonne<span class="token punctuation">(</span>central_meridian <span class="token operator">=</span> <span class="token number">112</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 0. Create a map frame for cartography</span></span>
<span class="line">mf <span class="token operator">=</span> plot<span class="token punctuation">.</span>MapFrame<span class="token punctuation">(</span>ax <span class="token operator">=</span> ax<span class="token punctuation">,</span> crs <span class="token operator">=</span> proj<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 1. Add built-in world country and administrative boundary vectors</span></span>
<span class="line">xly <span class="token operator">=</span> inres<span class="token punctuation">.</span>WorldLayer<span class="token punctuation">.</span>Country</span>
<span class="line">np<span class="token punctuation">.</span>random<span class="token punctuation">.</span>seed<span class="token punctuation">(</span><span class="token number">4</span><span class="token punctuation">)</span></span>
<span class="line">colors <span class="token operator">=</span> np<span class="token punctuation">.</span>random<span class="token punctuation">.</span>uniform<span class="token punctuation">(</span>size <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token builtin">len</span><span class="token punctuation">(</span>xly<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">ml1 <span class="token operator">=</span> mf<span class="token punctuation">.</span>add_vector<span class="token punctuation">(</span>xly<span class="token punctuation">,</span> facecolors <span class="token operator">=</span> colors<span class="token punctuation">,</span> edgecolors <span class="token operator">=</span> <span class="token string">'gray'</span><span class="token punctuation">,</span> linewidths <span class="token operator">=</span> <span class="token number">0.1</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 2. Add graticules</span></span>
<span class="line">gtl <span class="token operator">=</span> mf<span class="token punctuation">.</span>add_graticule<span class="token punctuation">(</span>lon_range <span class="token operator">=</span> <span class="token builtin">range</span><span class="token punctuation">(</span><span class="token operator">-</span><span class="token number">180</span><span class="token punctuation">,</span> <span class="token number">180</span><span class="token punctuation">,</span> <span class="token number">30</span><span class="token punctuation">)</span><span class="token punctuation">,</span> lat_range <span class="token operator">=</span> <span class="token builtin">range</span><span class="token punctuation">(</span><span class="token operator">-</span><span class="token number">90</span><span class="token punctuation">,</span> <span class="token number">90</span><span class="token punctuation">,</span> <span class="token number">15</span><span class="token punctuation">)</span><span class="token punctuation">,</span> </span>
<span class="line">                       linewidths <span class="token operator">=</span> <span class="token number">0.2</span><span class="token punctuation">,</span> ls <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token number">6</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token number">6</span><span class="token punctuation">,</span> <span class="token number">6</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token comment"># 2.1 Set the graticule frame border</span></span>
<span class="line">ol <span class="token operator">=</span> gtl<span class="token punctuation">.</span>set_outline<span class="token punctuation">(</span>linewidths <span class="token operator">=</span> <span class="token number">0.5</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre>
<div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><img src="/example.svg" alt=""></p>
</div></template>


